func TestClassifyFactDrift_StableRegisterPlusUncheckedToolStillFires(t *testing.T) {
    em, ok := classifyFactDrift(
        &evidenceFactRefresh{FactID: "sdlt-ftb-relief-cap", Outcome: "fresh"},
        sdltReliefCapFact(500000), fdTool("stamp-duty", false, true), nil, fdSiteIDStr)
    if !ok { t.Fatal("a stable register and an unchecked tool must still produce a finding — 225's exact shape") }
    if em.Kind != "unreconciled_declaration" { t.Fatalf("kind = %q", em.Kind) }
}

func TestPlanSiteFactDrift_UncheckedToolFiresWithoutReadingRegisterHistory(t *testing.T) {
    mock.ExpectQuery(regexp.QuoteMeta(factDriftIndexQuery)).WithArgs(fdSiteID).WillReturnRows(...)
    mock.ExpectQuery(regexp.QuoteMeta(factDriftLastItemQuery)).WithArgs(fdSiteID).
        WillReturnRows(sqlmock.NewRows([]string{"id","subject_key","new_value"}))  // never told anything
    // DELIBERATELY no further expectation: a re-added site_specs history read is an unexpected query
    plan := planSiteFactDrift(context.Background(), db, fdSiteID, eb, res, true, zap.NewNop())
    if len(plan.Emissions) != 1 || plan.Emissions[0].Kind != "unreconciled_declaration" {
        t.Fatalf("a stable register plus a never-reconciled tool must fire: %+v", plan.Emissions)
    }
}
